var n=`1168-cochinita-pibil`;var t=`world-1168`;var a=`MX`;var o=`central-america-caribbean`;var r=4;var s=325;var l={en:`Cochinita Pibil`,ua:`Кочініта пібіль`};var d={en:`Cochinita Pibil is a dish from Mexico prepared with pork shoulder, achiote paste, orange juice, lime juice. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Кочініта пібіль, страва кухні країни Мексика, яку готують із таких продуктів: свиняча лопатка, паста ачіоте, апельсиновий сік, сік лайма. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 100 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 100 хвилин.`,t:[`marinating`],m:100,i:[[`pork-shoulder`,1150,`g`],[`achiote-paste`,110,`g`],[`orange-juice`,170,`ml`],[`lime-juice`,50,`ml`],[`garlic`,5,`clove`],[`ground-cumin`,5,`g`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:12,i:[[`banana-leaf`,8,`leaf`]]},{en:`Roast the already seasoned food in a preheated oven until tender and safely cooked, using a thermometer for meat or poultry.`,ua:`Запікайте вже приправлені продукти в розігрітій духовці до м’якості та готовності, перевіряючи температуру м’яса термометром.`,t:[`roasting`],m:200,i:[]},{en:`Shred or tear the cooked components, then fold together with the listed additions.`,ua:`Нашаткуйте або розберіть готові компоненти на волокна й змішайте з зазначеними додатками.`,t:[`shredding`,`mixing`],m:9,i:[[`red-onion`,190,`g`],[`white-vinegar`,65,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`corn-tortillas`,12,`pcs`]]}];var c={slug:n,id:t,country:`MX`,region:o,servings:4,minutes:325,title:l,text:d,steps:h};export{a as country,c as default,t as id,s as minutes,o as region,r as servings,n as slug,h as steps,d as text,l as title};